academic:
CREATE TABLE author (aid INT PRIMARY KEY, homepage TEXT, name TEXT, oid INT);

CREATE TABLE cite (cited INT, citing INT, FOREIGN KEY (citing) REFERENCES publication(pid), FOREIGN KEY (cited) REFERENCES publication(pid));

CREATE TABLE conference (cid INT PRIMARY KEY, homepage TEXT, name TEXT);

CREATE TABLE domain (did INT PRIMARY KEY, name TEXT);

CREATE TABLE domain_author (aid INT PRIMARY KEY, did INT PRIMARY KEY, FOREIGN KEY (did) REFERENCES domain(did), FOREIGN KEY (aid) REFERENCES author(aid));

CREATE TABLE domain_conference (cid INT PRIMARY KEY, did INT PRIMARY KEY, FOREIGN KEY (did) REFERENCES domain(did), FOREIGN KEY (cid) REFERENCES conference(cid));

CREATE TABLE domain_journal (did INT PRIMARY KEY, jid INT PRIMARY KEY, FOREIGN KEY (did) REFERENCES domain(did), FOREIGN KEY (jid) REFERENCES journal(jid));

CREATE TABLE domain_keyword (did INT PRIMARY KEY, kid INT PRIMARY KEY, FOREIGN KEY (did) REFERENCES domain(did), FOREIGN KEY (kid) REFERENCES keyword(kid));

CREATE TABLE domain_publication (did INT PRIMARY KEY, pid INT PRIMARY KEY, FOREIGN KEY (did) REFERENCES domain(did), FOREIGN KEY (pid) REFERENCES publication(pid));

CREATE TABLE journal (homepage TEXT, jid INT PRIMARY KEY, name TEXT);

CREATE TABLE keyword (keyword TEXT, kid INT PRIMARY KEY);

CREATE TABLE organization (continent TEXT, homepage TEXT, name TEXT, oid INT PRIMARY KEY);

CREATE TABLE publication (abstract TEXT, cid TEXT, citation_num INT, jid INT, pid INT PRIMARY KEY, reference_num INT, title TEXT, year INT, FOREIGN KEY (cid) REFERENCES conference(cid), FOREIGN KEY (jid) REFERENCES journal(jid));

CREATE TABLE publication_keyword (pid INT PRIMARY KEY, kid INT PRIMARY KEY, FOREIGN KEY (kid) REFERENCES keyword(kid), FOREIGN KEY (pid) REFERENCES publication(pid));

CREATE TABLE writes (aid INT PRIMARY KEY, pid INT PRIMARY KEY, FOREIGN KEY (aid) REFERENCES author(aid), FOREIGN KEY (pid) REFERENCES publication(pid));

geo:
CREATE TABLE border_info (state_name TEXT PRIMARY KEY, border TEXT PRIMARY KEY, FOREIGN KEY (border) REFERENCES state(state_name), FOREIGN KEY (state_name) REFERENCES state(state_name));

CREATE TABLE city (city_name TEXT PRIMARY KEY, population INTEGER, country_name varchar(3), state_name TEXT PRIMARY KEY, FOREIGN KEY (state_name) REFERENCES state(state_name));

CREATE TABLE highlow (state_name TEXT PRIMARY KEY, highest_elevation TEXT, lowest_point TEXT, highest_point TEXT, lowest_elevation TEXT, FOREIGN KEY (state_name) REFERENCES state(state_name));

CREATE TABLE lake (lake_name TEXT, area double, country_name varchar(3), state_name TEXT);

CREATE TABLE mountain (mountain_name TEXT PRIMARY KEY, mountain_altitude INTEGER, country_name varchar(3), state_name TEXT PRIMARY KEY, FOREIGN KEY (state_name) REFERENCES state(state_name));

CREATE TABLE river (river_name TEXT PRIMARY KEY, length INTEGER, country_name varchar(3), traverse TEXT, FOREIGN KEY (traverse) REFERENCES state(state_name));

CREATE TABLE state (state_name TEXT PRIMARY KEY, population INTEGER, area double, country_name varchar(3), capital TEXT, density double);

imdb:
CREATE TABLE actor (aid INT PRIMARY KEY, gender TEXT, name TEXT, nationality TEXT, birth_city TEXT, birth_year INT);

CREATE TABLE cast (id INT PRIMARY KEY, msid INT, aid INT, role INT, FOREIGN KEY (msid) REFERENCES copyright(msid), FOREIGN KEY (aid) REFERENCES actor(aid));

CREATE TABLE classification (id INT PRIMARY KEY, msid INT, gid INT, FOREIGN KEY (msid) REFERENCES copyright(msid), FOREIGN KEY (gid) REFERENCES genre(gid));

CREATE TABLE company (id INT PRIMARY KEY, name TEXT, country_code TEXT);

CREATE TABLE copyright (id INT PRIMARY KEY, msid INT, cid INT);

CREATE TABLE directed_by (id INT PRIMARY KEY, msid INT, did INT, FOREIGN KEY (did) REFERENCES director(did), FOREIGN KEY (msid) REFERENCES copyright(msid));

CREATE TABLE director (did INT PRIMARY KEY, gender TEXT, name TEXT, nationality TEXT, birth_city TEXT, birth_year INT);

CREATE TABLE genre (gid INT PRIMARY KEY, genre TEXT);

CREATE TABLE keyword (id INT PRIMARY KEY, keyword TEXT);

CREATE TABLE made_by (id INT PRIMARY KEY, msid INT, pid INT, FOREIGN KEY (pid) REFERENCES producer(pid), FOREIGN KEY (msid) REFERENCES copyright(msid));

CREATE TABLE movie (mid INT PRIMARY KEY, title TEXT, release_year INT, title_aka TEXT, budget TEXT);

CREATE TABLE producer (pid INT PRIMARY KEY, gender TEXT, name TEXT, nationality TEXT, birth_city TEXT, birth_year INT);

CREATE TABLE tags (id INT PRIMARY KEY, msid INT, kid INT, FOREIGN KEY (kid) REFERENCES keyword(kid), FOREIGN KEY (msid) REFERENCES copyright(msid));

CREATE TABLE tv_series (sid INT PRIMARY KEY, title TEXT, release_year INT, num_of_seasons INT, num_of_episodes INT, title_aka TEXT, budget TEXT);

CREATE TABLE writer (wid INT PRIMARY KEY, gender TEXT, name INT, nationality INT, num_of_episodes INT, birth_city TEXT, birth_year INT);

CREATE TABLE written_by (id INT, msid INT, wid INT, FOREIGN KEY (wid) REFERENCES writer(wid), FOREIGN KEY (msid) REFERENCES copyright(msid));

