scholar:
CREATE TABLE author (authorId INTEGER PRIMARY KEY, authorName varchar(50));

CREATE TABLE cite (citingPaperId INTEGER PRIMARY KEY, citedPaperId INTEGER PRIMARY KEY, FOREIGN KEY (citingPaperId) REFERENCES paper(paperId), FOREIGN KEY (citedPaperId) REFERENCES paper(paperId));

CREATE TABLE dataset (datasetId INTEGER PRIMARY KEY, datasetName varchar(50));

CREATE TABLE journal (journalId INTEGER PRIMARY KEY, journalName varchar(100));

CREATE TABLE keyphrase (keyphraseId INTEGER PRIMARY KEY, keyphraseName varchar(50));

CREATE TABLE paper (paperId INTEGER PRIMARY KEY, title varchar(300), venueId INTEGER, year INTEGER, numCiting INTEGER, numCitedBy INTEGER, journalId INTEGER, FOREIGN KEY (venueId) REFERENCES venue(venueId), FOREIGN KEY (journalId) REFERENCES journal(journalId));

CREATE TABLE paperDataset (paperId INTEGER PRIMARY KEY, datasetId INTEGER PRIMARY KEY);

CREATE TABLE paperKeyphrase (paperId INTEGER PRIMARY KEY, keyphraseId INTEGER PRIMARY KEY, FOREIGN KEY (keyphraseId) REFERENCES keyphrase(keyphraseId), FOREIGN KEY (paperId) REFERENCES paper(paperId));

CREATE TABLE venue (venueId INTEGER PRIMARY KEY, venueName varchar(100));

CREATE TABLE writes (paperId INTEGER PRIMARY KEY, authorId INTEGER PRIMARY KEY, FOREIGN KEY (authorId) REFERENCES author(authorId), FOREIGN KEY (paperId) REFERENCES paper(paperId));

yelp:
CREATE TABLE business (bid INT PRIMARY KEY, business_id TEXT, name TEXT, full_address TEXT, city TEXT, latitude TEXT, longitude TEXT, review_count INT, is_open INT, rating REAL, state TEXT);

CREATE TABLE category (id INT PRIMARY KEY, business_id TEXT, category_name TEXT, FOREIGN KEY (business_id) REFERENCES business(business_id));

CREATE TABLE checkin (cid INT PRIMARY KEY, business_id TEXT, count INT, day TEXT, FOREIGN KEY (business_id) REFERENCES business(business_id));

CREATE TABLE neighbourhood (id INT PRIMARY KEY, business_id TEXT, neighbourhood_name TEXT, FOREIGN KEY (business_id) REFERENCES business(business_id));

CREATE TABLE review (rid INT PRIMARY KEY, business_id TEXT, user_id TEXT, rating REAL, text TEXT, year INT, month TEXT, FOREIGN KEY (user_id) REFERENCES user(user_id), FOREIGN KEY (business_id) REFERENCES business(business_id));

CREATE TABLE tip (tip_id INT PRIMARY KEY, business_id TEXT, text TEXT, user_id TEXT, likes INT, year INT, month TEXT, FOREIGN KEY (user_id) REFERENCES user(user_id), FOREIGN KEY (business_id) REFERENCES business(business_id));

CREATE TABLE user (uid INT PRIMARY KEY, user_id TEXT, name TEXT);
